import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func sheetTap(_ app:XCUIApplication,_ name:String){let b=app.buttons[name];XCTAssertTrue(b.waitForExistence(timeout:15),app.debugDescription);var n=0;while !b.isHittable && n<3{app.scrollViews.element(boundBy:app.scrollViews.count-1).swipeUp();n+=1};XCTAssertTrue(b.isHittable,app.debugDescription);b.tap()}
 func testNativeApplicationDraftKeepThenExplicitReplaceWithoutSend() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let meal=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA AI browser future meal,")).firstMatch;XCTAssertTrue(meal.waitForExistence(timeout:12),app.debugDescription);meal.tap();tap(app,"Request to join");let intro=app.textViews["Your introduction"];XCTAssertTrue(intro.waitForExistence(timeout:12));let original="QA original introduction is kept.";type(intro,original);XCTAssertEqual(intro.value as? String,original);app.staticTexts["Pull up a chair."].firstMatch.tap();let launcher=app.buttons["Ask Fancy"];XCTAssertTrue(launcher.waitForExistence(timeout:10),app.debugDescription);XCTAssertTrue(launcher.isHittable,app.debugDescription);launcher.tap();tap(app,"Continue conversation");let q=app.textViews["Ask Fancy a question"];XCTAssertTrue(q.waitForExistence(timeout:12));type(q,"Please draft my application.");let ask=app.buttons["Ask"];XCTAssertTrue(ask.isHittable,app.debugDescription);ask.tap();let use=app.buttons["Use text in form"];XCTAssertTrue(use.waitForExistence(timeout:20),app.debugDescription);sheetTap(app,"Use text in form");sheetTap(app,"Keep my text");tap(app,"Close");XCTAssertEqual(intro.value as? String,original);let keep=XCTAttachment(screenshot:app.screenshot());keep.name="native83-keep-existing-application-introduction";keep.lifetime = .keepAlways;add(keep);tap(app,"Ask Fancy");tap(app,"Continue conversation");sheetTap(app,"Use text in form");sheetTap(app,"Replace my text");let expected="I would enjoy joining this friendly table and meeting new neighbours.";let replaced=XCTNSPredicateExpectation(predicate:NSPredicate(format:"value == %@",expected),object:intro);XCTAssertEqual(XCTWaiter.wait(for:[replaced],timeout:12),.completed,app.debugDescription);XCTAssertTrue(intro.isHittable);XCTAssertTrue(app.buttons["Send request"].exists);print("QA_NATIVE83_EXPLICIT_DRAFT_TRANSFER_NO_SEND\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native83-explicit-replace-no-application-send";a.lifetime = .keepAlways;add(a)
 }
}
